def sp_term_has_constructor(term,name):
    todo=[term]
    while todo:
        item=todo.pop()
        if isinstance(item,list) and item:
            if item[0]==name:
                return True
            i=1
            while i<len(item):
                if isinstance(item[i],list):
                    todo.append(item[i])
                i+=1
    return False

def sp_same_support_ids(left,right):
    if not isinstance(left,list) or not isinstance(right,list):
        return False
    a=sp_unique(left)
    b=sp_unique(right)
    if not a or len(a)!=len(b):
        return False
    for value in a:
        if value not in b:
            return False
    return True

def sp_lost_exception_duplicate(row,qualified):
    if not isinstance(row,dict) or not isinstance(qualified,dict):
        return False
    term=row.get('term')
    other=qualified.get('term')
    if not isinstance(term,list) or not isinstance(other,list):
        return False
    if len(term)!=5 or len(other)!=5:
        return False
    if term[0]!='prohibition' or other[0]!='prohibition':
        return False
    if term[1]!=other[1] or term[2]!=other[2] or term[3]!=other[3]:
        return False
    if term[4]!=['no_exceptions'] or other[4]==['no_exceptions']:
        return False
    if not sp_term_has_constructor(term[2],'disclose'):
        return False
    if not sp_term_has_constructor(term[2],'confidential_information'):
        return False
    if not sp_term_has_constructor(other[4],'authorization_exception'):
        return False
    if not sp_term_has_constructor(other[4],'purpose_exception'):
        return False
    return sp_same_support_ids(row.get('support_ids',[]),qualified.get('support_ids',[]))

def sp_remove_lost_exception_duplicates(rows):
    out=[]
    for row in rows:
        remove=False
        if isinstance(row,dict):
            for qualified in rows:
                if sp_lost_exception_duplicate(row,qualified):
                    remove=True
                    break
        if not remove:
            out.append(row)
    return out

def apply(inputs,premises):
    spans=[]
    for span in inputs.get('source_spans',[]):
        if isinstance(span,dict):
            spans.append(span)
    old=inputs.get('source_output',{})
    statements=[]
    unresolved=[]
    if isinstance(old,dict):
        preserved=[]
        for row in old.get('statements',[]):
            if isinstance(row,dict):
                preserved.append(row)
        statements=sp_remove_lost_exception_duplicates(preserved)
        for item in old.get('unresolved',[]):
            if isinstance(item,str) and item not in unresolved:
                unresolved.append(item)
    disposal_count=0
    i=0
    while i<len(spans):
        uid=spans[i].get('id')
        raw=spans[i].get('text','')
        if not isinstance(raw,str):
            raw=str(raw)
        context=sp_context(spans,i,2,3)
        if sp_disposal_candidate(raw,context):
            positions=sp_action_positions(sp_low(raw))
            kinds=[]
            if positions[0]>=0:
                kinds.append('return')
            if positions[1]>=0:
                kinds.append('destroy')
            scope='unit:'+str(uid)
            triggers={}
            for kind in kinds:
                triggers[kind]=sp_trigger(raw,context,kind)
            linked=len(kinds)==2 and triggers.get('return')==triggers.get('destroy')
            mode='linked' if linked else 'atomic'
            exception=sp_exception(spans,i)
            support=[uid]
            support.extend(exception[3])
            for kind in kinds:
                action_id=scope+':'+kind
                material=sp_material(raw,kind)
                timing=sp_timing(raw,kind)
                sp_add(statements,['acq_disposal_action_v3',scope,action_id,kind,mode,material,triggers.get(kind),timing,exception[0],exception[1],exception[2],raw],support)
                disposal_count+=1
                if triggers.get(kind)=='unresolved_trigger':
                    unresolved.append('action trigger unresolved for '+action_id)
            if len(kinds)==2:
                connector='or' if ' or ' in sp_low(raw) else 'and' if ' and ' in sp_low(raw) else 'split_or'
                if not linked:
                    connector='split_or'
                sp_add(statements,['acq_disposal_link_v3',scope,scope+':return',scope+':destroy',connector,raw],[uid])
        i+=1
    sp_retention(spans,statements)
    sp_disclosure(spans,statements,unresolved)
    if disposal_count==0:
        ids=[]
        for span in spans:
            ids.append(span.get('id'))
        source_text=inputs.get('source_text','')
        if not isinstance(source_text,str):
            source_text=str(source_text)
        sp_add(statements,['acq_residual_v3','no_safely_composable_disposal_atom',source_text],ids)
        unresolved.append('no disposal atom acquired; complete-source absence is not asserted')
    statements=sp_remove_lost_exception_duplicates(statements)
    complete=isinstance(old,dict) and bool(old.get('complete',False)) and len(sp_unique(unresolved))==0
    return {'statements':statements,'complete':complete,'unresolved':sp_unique(unresolved)}
